import sys

def main():
    import sys
    import collections

    def read_input():
        n = int(sys.stdin.readline().strip())
        s = sys.stdin.readline().strip()
        return n, s

    def process(n, s):
        # Initialize counters for each group
        count_0 = collections.Counter()
        count_1 = collections.Counter()
        count_2 = collections.Counter()

        # Count colors in each group
        for i in range(n):
            if i % 3 == 0:
                count_0[s[i]] += 1
            elif i % 3 == 1:
                count_1[s[i]] += 1
            else:
                count_2[s[i]] += 1

        # Determine the most frequent color in each group
        max_count_0 = count_0.most_common(1)[0][0]
        max_count_1 = count_1.most_common(1)[0][0]
        max_count_2 = count_2.most_common(1)[0][0]

        # Calculate the number of recolors needed
        recolors = 0
        result = []

        for i in range(n):
            if i % 3 == 0:
                if s[i] != max_count_0:
                    recolors += 1
                result.append(max_count_0)
            elif i % 3 == 1:
                if s[i] != max_count_1:
                    recolors += 1
                result.append(max_count_1)
            else:
                if s[i] != max_count_2:
                    recolors += 1
                result.append(max_count_2)

        return recolors, ''.join(result)

    n, s = read_input()
    r, t = process(n, s)
    print(r)
    print(t)

if __name__ == "__main__":
    main()
